    "use strict";
    /* ==================== UTILITIES & STATE ==================== */
    const $=(s,r)=> (r||document).querySelector(s);
    const $$=(s,r)=> Array.from((r||document).querySelectorAll(s));
    const fmt$=n=> "$"+Number(n).toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2});
    const fmtN=n=> Number(n).toLocaleString("en-US");
    const fmtMult=m=> (m>=100? Math.floor(m) : Math.round(m*100)/100).toFixed(2)+"×";
    const nowT=()=> new Date().toLocaleTimeString("en-GB",{hour:"2-digit",minute:"2-digit",second:"2-digit"});
    const esc=s=> String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
    function toast(title,sub,type){
      const box=$("#toasts"); const t=document.createElement("div");
      t.className="toast"+(type?" "+type:"");
      t.innerHTML="<div><b>"+esc(title)+"</b>"+(sub?"<span>"+esc(sub)+"</span>":"")+"</div>";
      box.appendChild(t);
      setTimeout(()=>{t.classList.add("out"); setTimeout(()=>t.remove(),320);},4200);
    }
    /* sound (WebAudio, created on first user gesture) */
    let AC=null;
    function beep(freq,dur,type,vol,when){
      if(!state.sound) return;
      try{
        AC=AC||new (window.AudioContext||window.webkitAudioContext)();
        if(AC.state==="suspended") AC.resume();
        const o=AC.createOscillator(), g=AC.createGain(), t0=AC.currentTime+(when||0);
        o.type=type||"sine"; o.frequency.value=freq;
        g.gain.setValueAtTime(vol||0.05,t0); g.gain.exponentialRampToValueAtTime(0.0001,t0+(dur||0.12));
        o.connect(g).connect(AC.destination); o.start(t0); o.stop(t0+(dur||0.12)+0.02);
      }catch(e){}
    }
    const sfx={
      click(){beep(620,0.05,"triangle",0.03);},
      win(){beep(660,0.12,"sine",0.06);beep(880,0.14,"sine",0.06,0.09);beep(1320,0.2,"sine",0.05,0.19);},
      big(){[523,659,784,1046,1318].forEach((f,i)=>beep(f,0.16,"triangle",0.06,i*0.08));},
      lose(){beep(220,0.18,"sawtooth",0.03);},
      coin(){beep(1180,0.07,"square",0.035);beep(1560,0.1,"square",0.03,0.06);}
    };

