    /* ---- shared: unified in-stage game header (logo medallion + name + sub + RTP + playing count) ---- */
    function gameHeaderHtml(id){
      var g=(typeof GAMES!=="undefined"&&GAMES[id])?GAMES[id]:{name:id,sub:"",rtp:"",players:0};
      var logo=(typeof GAME_LOGOS!=="undefined"&&GAME_LOGOS[id])?GAME_LOGOS[id]:"";
      var art= g.img? '<img src="'+g.img+'" alt="" />' : ((typeof TILE_ARTS!=="undefined"&&TILE_ARTS[id])?TILE_ARTS[id]:"");
      return '<div class="gh-wrap gh-logo">'
        +'<div class="gh-art">'+art+'<div class="gh-shade"></div><div class="gh-medal">'+logo+'</div>'
        +'<div class="gh-badges"><span class="gh-rtp">'+esc(g.rtp||"")+'</span>'
        +'<span class="gh-live"><i class="live-dot"></i><span>'+Number(g.players||0).toLocaleString("en-US")+'</span>&nbsp;playing</span></div>'
        +'<span class="gh-sr">'+esc(g.name)+'</span></div></div>';
    }
    /* ---- game title lockup: artwork + logo medallion instead of a text name ---- */
    function gameLogoLockup(id){
      var g=(typeof GAMES!=="undefined"&&GAMES[id])?GAMES[id]:{name:id};
      var logo=(typeof GAME_LOGOS!=="undefined"&&GAME_LOGOS[id])?GAME_LOGOS[id]:"";
      var art= g.img? '<img src="'+g.img+'" alt="" />' : ((typeof TILE_ARTS!=="undefined"&&TILE_ARTS[id])?TILE_ARTS[id]:"");
      return '<span class="gt-logo"><span class="gl-art">'+art+'</span><span class="gl-medal">'+logo+'</span><span class="gh-sr">'+esc(g.name)+'</span></span>';
    }
    /* ---- avatar system: gradient initials + emblem picker ---- */
    const AV_GRADS=[["#f5b942","#b45309"],["#00e065","#0a8f5c"],["#60a5fa","#1d4ed8"],["#f472b6","#a21caf"],["#a78bfa","#5b21b6"],["#f87171","#991b1b"],["#2dd4bf","#0f766e"],["#fb923c","#c2410c"],["#94a3b8","#334155"],["#e879f9","#86198f"],["#4ade80","#166534"],["#38bdf8","#0c4a6e"]];
    function hashName(n){ n=String(n||"?"); let h=0; for(let i=0;i<n.length;i++) h=(h*31+n.charCodeAt(i))>>>0; return h%AV_GRADS.length; }
    function avInitHtml(name,size){ const g=AV_GRADS[hashName(name)]; const ch=String(name||"?").trim().charAt(0).toUpperCase()||"?"; return '<span class="bv-av '+size+'" style="--a1:'+g[0]+';--a2:'+g[1]+'">'+esc(ch)+'</span>'; }
    function avMiniHtml(name){ return avInitHtml(name,"xs"); }
