    function avEmblemHtml(i,size){ const a=AVATARS[i]; return '<span class="bv-av '+size+' av-emb" style="--a1:'+a.c[0]+';--a2:'+a.c[1]+'">'+a.svg+'</span>'; }
    function userAvHtml(size){ const u=state.user; if(u&&u.avatar!=null&&AVATARS[u.avatar]) return avEmblemHtml(u.avatar,size); return avInitHtml(u?u.name:"?",size); }
    function podAvHtml(name,rank){ const u=state.user; const ring=rank===1?"ring-gold":rank===2?"ring-silver":"ring-bronze"; if(u&&name===u.name) return userAvHtml("lg "+ring); return avInitHtml(name,"lg "+ring); }
    function renderAvatar(){
      const u=state.user; if(!u) return;
      const art=(u.avatar!=null&&AVATARS[u.avatar])? avEmblemHtml(u.avatar,"nav") : avInitHtml(u.name,"nav");
      const ab=$("#avatarBtn"); if(ab){ ab.innerHTML=art; ab.style.display="flex"; }
      const pa=$("#profAvatar"); if(pa) pa.innerHTML=(u.avatar!=null&&AVATARS[u.avatar])? avEmblemHtml(u.avatar,"prof") : avInitHtml(u.name,"prof");
      $$("#avPicker .av-opt").forEach((el,i)=>{ el.classList.toggle("on",i===u.avatar); el.setAttribute("aria-checked",i===u.avatar?"true":"false"); });
    }
    function initAvatarPicker(){
      const wrap=$("#avPicker"); if(!wrap||wrap.dataset.done) return; wrap.dataset.done="1";
      wrap.innerHTML=AVATARS.map((a,i)=>'<button class="av-opt" role="radio" aria-checked="false" data-av="'+i+'" aria-label="'+a.n+' avatar"><span class="bv-av av-emb" style="--a1:'+a.c[0]+';--a2:'+a.c[1]+'">'+a.svg+'</span><small>'+a.n+'</small></button>').join("");
      wrap.addEventListener("click",e=>{
        const b=e.target.closest("[data-av]"); if(!b||!state.user) return;
        state.user.avatar=parseInt(b.dataset.av,10);
        renderAvatar(); if(state.view==="leaderboard") renderLeaderboard(); sfx.click();
        toast("Avatar updated","Your new look is live across Betvora.");
      });
    }
    initAvatarPicker();
    const state={
      user:null, joined:null, balance:0, sound:true, anim:true,
      myBets:[], txs:[], rewards:[], totalWagered:0, biggestWin:0,
      lastDeposit:0, wageredSinceDeposit:0,
      raceJoined:false, cashbackClaimed:false, welcomeClaimed:false,
      firstDepositDone:false, reloadClaimed:false, dailyClaimed:false, spinsClaimed:false,
      levelupClaimed:false, birthdayClaimed:false, raffleJoined:false, tourneyJoined:false,
      rakeback:0, feedTab:"all", view:"lobby", game:null, search:""
    };
    function renderBalance(){
      const bal=_cleanNum(state.balance);
      tweenFromLast($("#balanceText"),bal,function(v){ return fmt$(v).slice(1); },600);
      tweenFromLast($("#walletBalance"),bal,fmt$,600);
    }
    function addTx(type,label,amount){
      state.txs.unshift({type:type,label:label,amount:amount,time:nowT()});
      renderTxs();
    }
    function renderTxs(){
      const html=state.txs.length? state.txs.map(tx=>{
        const ic= tx.type==="dep"
          ? '<span class="tx-ic" style="background:rgba(0,224,101,.13);color:var(--green)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 4v11m0 0 4.5-4.5M12 15 7.5 10.5M4 20h16"/></svg></span>'
          : tx.type==="wd"
          ? '<span class="tx-ic" style="background:rgba(255,92,92,.12);color:var(--red)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 15V4m0 0L7.5 8.5M12 4l4.5 4.5M4 20h16"/></svg></span>'
          : '<span class="tx-ic" style="background:rgba(245,185,66,.13);color:var(--gold)"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"><path d="M20 12v9H4v-9M2 7h20v5H2zM12 21V7m0 0H7.5a2.5 2.5 0 1 1 0-5C11 2 12 7 12 7Zm0 0h4.5a2.5 2.5 0 1 0 0-5C13 2 12 7 12 7Z"/></svg></span>';
        return '<div class="tx-row">'+ic+'<div><b>'+esc(tx.label)+'</b><span>'+tx.time+'</span></div><span class="tx-amt" style="color:'+(tx.amount>=0?"var(--green)":"var(--red)")+'">'+(tx.amount>=0?"+":"−")+" "+fmt$(Math.abs(tx.amount))+"</span></div>";
      }).join("") : Empty.txs();
      $("#walletTxList").innerHTML=html;
      $("#myTxList").innerHTML=html;
      const pt=$("#profTxList"); if(pt) pt.innerHTML=html;
    }
    function recordBet(gameName,bet,mult,payout){
      const row={game:gameName,player:state.user?state.user.name:"You",time:nowT(),bet:bet,mult:mult,payout:payout};
      state.myBets.unshift(row);
      state.totalWagered+=bet;
      state.wageredSinceDeposit+=bet;
      if(typeof renderTurnover==="function") renderTurnover();
      state.biggestWin=Math.max(state.biggestWin,payout);
      state.rakeback+=bet*0.002;
      renderMyBets(); renderVip(); renderRace();
      return row;
    }
    function renderMyBets(){
      const prof=state.myBets.reduce((a,b)=>a+(b.payout-b.bet),0);
      $("#stWagered").textContent=fmt$(state.totalWagered);
      $("#stBets").textContent=fmtN(state.myBets.length);
      $("#stBigWin").textContent=fmt$(state.biggestWin);
      const pEl=$("#stProfit"); pEl.textContent=(prof<0?"−":"")+fmt$(Math.abs(prof)); pEl.style.color=prof>=0?"var(--green)":"var(--red)";
      renderMyBetsTable();
      renderProfile();
      if(state.feedTab==="mine") renderFeed();
    }
    function rowHtml(r){
      const net=r.payout-r.bet;
      const multCell=r.mult>0?"<span class='mult-chip"+(r.mult>=2?" hot":"")+"'>"+fmtMult(r.mult)+"</span>":"<span class='mult-chip muted'>—</span>";
      return "<tr><td>"+esc(r.game)+"</td><td><span class='p-who'>"+avMiniHtml(r.player)+"<span>"+esc(r.player)+"</span></span></td><td class='col-time mono'>"+r.time+"</td><td class='mono'>"+fmt$(r.bet)+"</td><td class='col-mult'>"+multCell+"</td><td style='text-align:right' class='"+(net>0?"win":"lose")+" mono'>"+(net>0?"+":"")+ (net!==0? (net>0?fmt$(net):"−"+fmt$(Math.abs(net))) : fmt$(0))+"</td></tr>";
    }
    function myRowHtml(r){
      const net=r.payout-r.bet;
      const multCell=r.mult>0?"<span class='mult-chip"+(r.mult>=2?" hot":"")+"'>"+fmtMult(r.mult)+"</span>":"<span class='mult-chip muted'>—</span>";
      return "<tr><td>"+esc(r.game)+"</td><td class='col-time mono'>"+r.time+"</td><td class='mono'>"+fmt$(r.bet)+"</td><td class='col-mult'>"+multCell+"</td><td style='text-align:right' class='"+(net>0?"win":"lose")+" mono'>"+(net>0?"+"+fmt$(net): net<0?"−"+fmt$(Math.abs(net)):fmt$(0))+"</td></tr>";
    }
    /* proper row for my-bets view */
    function renderMyBetsTable(){
      $("#myBetsBody").innerHTML= state.myBets.length? state.myBets.slice(0,30).map(myRowHtml).join("") : '<tr class="empty-row"><td colspan="5">'+Empty.bets()+'</td></tr>';
    }
    /* ==================== SITE MOTION (scroll reveal) ==================== */
    function initMotion(){
      if(!state.anim) document.documentElement.classList.add("no-motion");
      if(matchMedia("(prefers-reduced-motion: reduce)").matches){
        state.anim=false; document.documentElement.classList.add("no-motion");
        const asw=$("#animSwitch"); if(asw){ asw.classList.remove("on"); asw.setAttribute("aria-checked","false"); }
      }
      if(!state.anim || matchMedia("(prefers-reduced-motion: reduce)").matches || !("IntersectionObserver" in window)) return;
      const sel=".hero,.stat-card,.sec-head,.row-strip,.cb-banner,.reg-banner,.offer-card,.promo-card,.tier,.table-wrap,.foot-band,.prof-head,.prof-grid,.my-stats,.card";
      const els=[...document.querySelectorAll(sel)].filter(el=>!el.closest(".overlay"));
      const counts=new Map();
      els.forEach(el=>{
        const n=counts.get(el.parentNode)||0; counts.set(el.parentNode,n+1);
        el.style.setProperty("--rvd",Math.min(n*70,350)+"ms");
      });
      const io=new IntersectionObserver(entries=>{
        entries.forEach(en=>{
          if(!en.isIntersecting) return;
          const el=en.target; io.unobserve(el); el.classList.add("rv-play");
          const clear=()=>{ el.classList.remove("rv-play"); el.style.removeProperty("--rvd"); };
          el.addEventListener("animationend",clear,{once:true});
          setTimeout(clear,1800);
        });
      },{threshold:.05,rootMargin:"0px 0px -6% 0px"});
      els.forEach(el=>io.observe(el));
    }
    /* ==================== SPLASH ==================== */
    (function(){
      const sp=document.getElementById("splash"); if(!sp) return;
      document.body.style.overflow="hidden";
      let done=false;
      const hide=()=>{ if(done) return; done=true; sp.classList.add("splash-hide"); document.body.style.overflow=""; setTimeout(()=>{ if(sp.parentNode) sp.remove(); },650); };
      setTimeout(hide, matchMedia("(prefers-reduced-motion: reduce)").matches? 500 : 2150);
      sp.addEventListener("click",hide);
    })();
/* ==========================================================================
   Betvora polish — view-transition helpers (presentation only, <40 lines).
   Paste into the main <script> right before the INIT block (see INTEGRATION.md).
   Same top-level scope as navigate()/openGame()/openSection(), so the
   functions below can be called from them directly.
   ========================================================================== */

/* Re-trigger the .view enter animation reliably. CSS animations restart when
   .active is re-added only if a style recalc happened in between — without the
   forced reflow, re-navigating to the already-active view (e.g. clicking the
   logo while on lobby) would silently skip the animation. Harmless for the
   normal case (different view becomes .active); one layout per navigation. */
function retriggerView(el){
  if(!el) return;
  el.classList.remove("active");
  void el.offsetWidth; /* forced reflow: flush the removal before re-adding */
  el.classList.add("active");
}

/* OPTIONAL animated overlay close (default: keep the existing instant close).
   Works with the .overlay.closing CSS in transitions.css. Skips the delay when
   animations are off so closing stays instant and fully usable.
   To enable: point closeOverlay() at this helper (see INTEGRATION.md). */
function closeOverlayAnim(id){
  var ov=document.getElementById(id);
  if(!ov||!ov.classList.contains("open")) return;
  var still=document.documentElement.classList.contains("no-motion")
    ||(window.matchMedia&&matchMedia("(prefers-reduced-motion: reduce)").matches);
  if(still||ov.classList.contains("closing")){ ov.classList.remove("open"); return; }
  ov.classList.add("closing");
  setTimeout(function(){ ov.classList.remove("open","closing"); },160);
}

/* ============================================================
   Betvora — skeleton + empty-state helpers (polish pass, presentation only)
   INSERT: paste this whole IIFE right before the INIT section:
    /* ==================== ANIMATED NUMBERS (polish pass) ====================
       rAF number tweens — presentation only.
       INSERTION: paste this whole block BEFORE the INIT section marker
       (the line reading: ==== INIT ====, with equals-sign borders).
       Paste exactly once.

       Semantics:
       - tweenNum(el, from, to, fmtFn, dur): tweens the element's text from
         `from` to `to` (~600ms default, ease-out cubic), formatting every
         frame with fmtFn. Guards:
           * overlapping tweens on the same element: the in-flight tween is
             cancelled before the new one starts (no fighting/jitter);
           * NaN / non-finite inputs are coerced to 0 — numbers can NEVER
             show NaN and can never get stuck mid-tween (each frame snaps
             the final value exactly on completion);
           * when animations are off (Settings toggle, prefers-reduced-motion,
             or html.no-motion) the value is set instantly — behavior is then
             identical to the direct textContent code this replaces.
       - tweenFromLast(el, to, fmtFn, dur): convenience for live counters —
         tweens from the last value this element was tweened to (0 on first
         use). No caller-side "from" tracking needed.
       - countUp() (the page's existing helper) is re-pointed at tweenNum()
         via a one-line body replacement (see INTEGRATION.md), so every
         existing game call-site gets the overlap/NaN guards for free.
       Reuses the page's own conventions: fmt$/fmtN formatters, and the
       `typeof ngAnim==="function" ? ngAnim() : fallback` pattern already
       used by flyChip(), because ngAnim() is declared in a nested scope and
       may not be visible here.
    */
    const _tweenRAF=new WeakMap();  // element -> pending rAF id (overlap guard)
    const _tweenLast=new WeakMap(); // element -> last tweened target value
    function _cleanNum(v){ const n=Number(v); return Number.isFinite(n)?n:0; }
    function _animOK(){
      try{ if(typeof ngAnim==="function") return !!ngAnim(); }catch(e){}
      if(window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches) return false;
      return !document.documentElement.classList.contains("no-motion");
    }
    function tweenNum(el,from,to,fmtFn,dur){
      if(!el) return;
      const pend=_tweenRAF.get(el);
      if(pend){ cancelAnimationFrame(pend); _tweenRAF.delete(el); }
      from=_cleanNum(from); to=_cleanNum(to);
      if(typeof fmtFn!=="function") fmtFn=function(v){ return fmt$(v); };
      dur=(typeof dur==="number"&&dur>0)?dur:600;
      _tweenLast.set(el,to);
      if(!_animOK()||from===to){ el.textContent=fmtFn(to); return; }
      const t0=performance.now();
      const step=function(t){
        let p=(t-t0)/dur; if(!(p>=0))p=0; if(p>1)p=1;  // NaN-proof progress
        const e=1-Math.pow(1-p,3);                      // ease-out cubic
        el.textContent=fmtFn(from+(to-from)*e);
        if(p<1){ _tweenRAF.set(el,requestAnimationFrame(step)); }
        else{ _tweenRAF.delete(el); el.textContent=fmtFn(to); } // exact snap: never stuck mid-tween
      };
      _tweenRAF.set(el,requestAnimationFrame(step));
    }
    /* Tween from the last value this element showed (0 on first use). */
    function tweenFromLast(el,to,fmtFn,dur){
      tweenNum(el,_tweenLast.has(el)?_tweenLast.get(el):0,to,fmtFn,dur);
    }
    /* Pre-seed: parse what's already on screen so the first tick tweens from
       the visible value instead of from 0. Runs once at insert time (this
       script sits at the end of <body>, so the DOM is ready). */
    (function(){
      ["jackpotVal","paidVal","onlineVal","balanceText","walletBalance"].forEach(function(id){
        const el=document.getElementById(id); if(!el) return;
        const v=parseFloat(String(el.textContent).replace(/[^0-9.\-]/g,""));
        if(Number.isFinite(v)) _tweenLast.set(el,v);
      });
    })();
